def solve():
    tiles = input().split()

    # Check if already have a mentsu
    # Check for koutsu (three identical tiles)
    if tiles[0] == tiles[1] == tiles[2]:
        return 0

    # Check for shuntsu (sequence)
    suits = {}
    for tile in tiles:
        num = int(tile[0])
        suit = tile[1]
        if suit not in suits:
            suits[suit] = []
        suits[suit].append(num)

    for suit, nums in suits.items():
        if len(nums) == 3:
            nums.sort()
            if nums[1] == nums[0] + 1 and nums[2] == nums[1] + 1:
                return 0

    # Check if can form mentsu with 1 tile
    # Check for forming koutsu
    tile_counts = {}
    for tile in tiles:
        tile_counts[tile] = tile_counts.get(tile, 0) + 1

    for tile, count in tile_counts.items():
        if count == 2:
            return 1

    # Check for forming shuntsu with 1 tile
    for suit, nums in suits.items():
        if len(nums) >= 2:
            nums.sort()
            for i in range(len(nums)):
                for j in range(i+1, len(nums)):
                    diff = nums[j] - nums[i]
                    if diff == 1:
                        # Can add nums[i]-1 or nums[j]+1
                        if nums[i] > 1 or nums[j] < 9:
                            return 1
                    elif diff == 2:
                        # Can add the middle number
                        return 1

    # Need 2 tiles
    return 2

