def solve():
    n, k = map(int, input().split())
    p = list(map(int, input().split()))

    used = set(p)
    remaining = sorted([i for i in range(1, n+1) if i not in used], reverse=True)

    def is_stack_sortable(arr):
        stack = []
        b = []
        next_needed = 1

        for x in arr:
            stack.append(x)
            while stack and stack[-1] == next_needed:
                b.append(stack.pop())
                next_needed += 1

        while stack:
            if stack[-1] != next_needed:
                return False
            b.append(stack.pop())
            next_needed += 1

        return len(b) == n

    def can_extend(prefix, remaining_nums):
        if not remaining_nums:
            return is_stack_sortable(prefix)

        stack = []
        next_needed = 1

        for x in prefix:
            stack.append(x)
            while stack and stack[-1] == next_needed:
                stack.pop()
                next_needed += 1

        if not stack:
            return True

        min_remaining = min(remaining_nums)
        if min_remaining < next_needed:
            return False

        for i in range(len(stack)-1):
            if stack[i] < stack[i+1]:
                return False

        return True

    result = p[:]

    for pos in range(k, n):
        found = False
        for i in range(len(remaining)):
            result.append(remaining[i])
            temp_remaining = remaining[:i] + remaining[i+1:]

            if can_extend(result, temp_remaining):
                remaining = temp_remaining
                found = True
                break

            result.pop()

        if not found:
            print(-1)
            return

    if is_stack_sortable(result):
        print(*result)
    else:
        print(-1)

solve()
