def safe_power(base, exp):
    if base == 0 and exp <= 0:
        return float('-inf')
    if base < 0 and exp != int(exp):
        return float('-inf')
    try:
        if base == 0:
            return 0
        if exp > 500:
            return float('inf') if base > 1 else 0
        result = base ** exp
        if math.isnan(result) or math.isinf(result):
            return float('inf') if base > 1 and exp > 0 else float('-inf')
        return result
    except:
        return float('-inf')

def safe_exp_exp(base, exp1, exp2):
    try:
        if exp2 > 500:
            inner = float('inf') if exp1 > 1 else 0
        else:
            inner = safe_power(exp1, exp2)
        if math.isinf(inner):
            return float('inf') if base > 1 else 0
        return safe_power(base, inner)
    except:
        return float('-inf')

expressions = [
    ("x^y^z", safe_exp_exp(x, y, z)),
    ("x^z^y", safe_exp_exp(x, z, y)),
    ("(x^y)^z", safe_power(safe_power(x, y), z)),
    ("(x^z)^y", safe_power(safe_power(x, z), y)),
    ("y^x^z", safe_exp_exp(y, x, z)),
