# Check if n teams play round-robin (odd number of teams)
# For x teams: x*(x-1)/2 = n
# x^2 - x - 2n = 0
# x = (1 + sqrt(1 + 8n)) / 2
discriminant = 1 + 8 * n
if discriminant >= 0:
    sqrt_d = int(discriminant ** 0.5)
