    if teams % 2 == 0:
        games = 0
        current_teams = teams

        while current_teams % 2 == 0:
            games += current_teams // 2
            current_teams //= 2

        if current_teams > 1:
            games += current_teams * (current_teams - 1) // 2

        if games == n:
            results.append(teams)

