def solve():
    n, T = map(int, input().split())
    songs = []
    for i in range(n):
        t, g = map(int, input().split())
        songs.append((t, g, i))

    MOD = 10**9 + 7

    def count_playlists(mask, remaining_time, last_genre):
        if remaining_time == 0:
            return 1
        if remaining_time < 0:
            return 0

        total = 0
        for i in range(n):
            if mask & (1 << i):
                continue

            song_time, song_genre, _ = songs[i]

            if song_genre == last_genre:
                continue

            if song_time <= remaining_time:
                total = (total + count_playlists(mask | (1 << i), remaining_time - song_time, song_genre)) % MOD

        return total

    result = count_playlists(0, T, -1)
    print(result)

