    while num % 10 == 9:
        count += 1
        num //= 10
    return count

def find_pairs_with_sum(target_sum, n):
    count = 0
    for i in range(1, min(n, target_sum)):
        j = target_sum - i
        if j > i and j <= n:
            count += 1
    return count

