import math

def factorial(n):
    if n > 18:
        return 10**18
    return math.factorial(n)

n, k, S = map(int, input().split())
a = list(map(int, input().split()))

mid = n // 2
count = 0

left_sums = {}
for mask in range(1 << mid):
    chosen = []
    for i in range(mid):
        if mask & (1 << i):
            chosen.append(i)

    if not chosen:
        continue

    for excl_mask in range(1 << len(chosen)):
        excl_count = 0
        total = 0
        for j, idx in enumerate(chosen):
            if excl_mask & (1 << j):
                excl_count += 1
                total += factorial(a[idx])
            else:
                total += a[idx]
            if total > S:
                break

        if excl_count <= k and total <= S:
            key = (total, excl_count)
            if key not in left_sums:
                left_sums[key] = 0
            left_sums[key] += 1

right_sums = {}
for mask in range(1 << (n - mid)):
    chosen = []
    for i in range(n - mid):
        if mask & (1 << i):
            chosen.append(mid + i)

    if not chosen:
        continue

    for excl_mask in range(1 << len(chosen)):
        excl_count = 0
        total = 0
        for j, idx in enumerate(chosen):
            if excl_mask & (1 << j):
                excl_count += 1
                total += factorial(a[idx])
            else:
                total += a[idx]
            if total > S:
                break

        if excl_count <= k and total <= S:
            key = (total, excl_count)
            if key not in right_sums:
                right_sums[key] = 0
            right_sums[key] += 1

for (left_sum, left_excl), left_count in left_sums.items():
    if left_sum == S and left_excl <= k:
        count += left_count

for (right_sum, right_excl), right_count in right_sums.items():
    if right_sum == S and right_excl <= k:
        count += right_count

for (left_sum, left_excl), left_count in left_sums.items():
    for (right_sum, right_excl), right_count in right_sums.items():
        if left_sum + right_sum == S and left_excl + right_excl <= k:
            count += left_count * right_count

print(count)
