def solve():
    n = int(input())
    k = input().strip()

    def convert_to_decimal(s, base):
        result = 0
        power = 0
        i = len(s) - 1
        while i >= 0:
            j = i
            while j >= 0 and s[j].isdigit():
                j -= 1
            digit_str = s[j+1:i+1]
            if digit_str:
                digit = int(digit_str)
                if digit >= base:
                    return -1
                result += digit * (base ** power)
                power += 1
            i = j
        return result

    min_result = float('inf')

    def try_parse(s, pos, current_digits):
        nonlocal min_result

        if pos == len(s):
            if current_digits:
                val = convert_to_decimal(''.join(map(str, current_digits[::-1])), n)
                if val != -1 and val <= 10**18:
                    min_result = min(min_result, val)
            return

        for end in range(pos + 1, min(pos + 10, len(s) + 1)):
            digit_str = s[pos:end]
            if digit_str[0] == '0' and len(digit_str) > 1:
                continue
