    digits = [int(d) for d in str(num)]

    def backtrack(idx, used):
        if idx == len(digits):
            return True

        for i in range(len(cubes)):
            if i not in used and digits[idx] in cubes[i]:
                used.add(i)
                if backtrack(idx + 1, used):
                    return True
                used.remove(i)

        return False

