def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def euler_phi(n):
    result = n
    p = 2
    while p * p <= n:
        if n % p == 0:
            while n % p == 0:
                n //= p
            result -= result // p
        p += 1
    if n > 1:
        result -= result // n
    return result

def find_order(x, m):
    if gcd(x, m) != 1:
        return -1

    phi = euler_phi(m)
    divisors = []
    i = 1
    while i * i <= phi:
        if phi % i == 0:
            divisors.append(i)
            if i != phi // i:
                divisors.append(phi // i)
        i += 1

    divisors.sort()

    for d in divisors:
        if pow(x, d, m) == 1:
            return d

    return phi

