def count_paths_through(y, n):
    if y > n:
        return 0

    count = 0
    current = y

    while current <= n:
        if current <= n:
            count += 1

        next_even = current * 2
        next_odd = current + 1

        if next_even <= n:
            count += 1

        if next_odd <= n and next_odd != next_even:
            count += 1

        if next_even > n and next_odd > n:
            break

        current = min(next_even, next_odd)
        if current > n:
            break

    return count

def count_reachable(y, n):
    if y > n:
        return 0

    count = 0
    queue = [y]
    visited = set([y])

    while queue:
        current = queue.pop(0)
        if current <= n:
            count += 1

        next_even = current * 2
        if next_even <= n and next_even not in visited:
            visited.add(next_even)
            queue.append(next_even)

        next_odd = current + 1
        if next_odd <= n and next_odd % 2 == 0:
            continue
        if next_odd <= n and next_odd not in visited:
            visited.add(next_odd)
            queue.append(next_odd)

    return count

def solve(n, k):
    left, right = 1, n
    result = 1

    while left <= right:
        mid = (left + right) // 2

        count = 0
        current = mid
        while current <= n:
            count += n // current
            if current > n // 2:
                break
            current *= 2

        if count >= k:
            result = mid
            left = mid + 1
        else:
            right = mid - 1

    return result

