def solve(n):
    MOD = 998244353

    def count_perfect_height(n):
        if n == 0:
            return 0
        h = 0
        while (1 << (h + 1)) - 1 < n:
            h += 1
        return h

    def is_perfect_shape(n):
        if n == 0:
            return True
        h = count_perfect_height(n)
        full = (1 << h) - 1
        if n <= full:
            return False
        last_level = n - full
        max_last = 1 << h
        if last_level > max_last:
            return False

        def check_subtree_sizes(total, height):
            if height == 0:
                return total == 1
            if total == 0:
                return True
            full_size = (1 << height) - 1
            if total <= full_size:
                return False
            if total == (1 << (height + 1)) - 1:
                return True
            last = total - full_size
            max_last = 1 << height
            if last > max_last:
                return False

            left_last = min(last, 1 << (height - 1))
            right_last = last - left_last

            left_size = (1 << (height - 1)) - 1 + left_last
            right_size = (1 << (height - 1)) - 1 + right_last

            return check_subtree_sizes(left_size, height - 1) and check_subtree_sizes(right_size, height - 1)

        return check_subtree_sizes(n, h)

    if not is_perfect_shape(n):
        return 0

    def factorial(n):
        result = 1
        for i in range(1, n + 1):
            result = (result * i) % MOD
        return result

    def modinv(a):
        return pow(a, MOD - 2, MOD)

    def binomial(n, k):
        if k > n or k < 0:
            return 0
        if k == 0 or k == n:
            return 1
        num = factorial(n)
        den = (factorial(k) * factorial(n - k)) % MOD
        return (num * modinv(den)) % MOD

    def count_striped(n):
        if n == 0:
            return 1
        if n == 1:
            return 1

        h = count_perfect_height(n)
        full = (1 << h) - 1
        last = n - full

        left_last = min(last, 1 << (h - 1))
        right_last = last - left_last

        left_size = (1 << (h - 1)) - 1 + left_last
        right_size = (1 << (h - 1)) - 1 + right_last

        odd_count = (n + 1) // 2
        even_count = n // 2

        result = 0

        for root_odd in [True, False]:
            if root_odd:
                left_even = (left_size + 1) // 2
                left_odd = left_size // 2
                right_odd = (right_size + 1) // 2
                right_even = right_size // 2

                if left_even + right_even != even_count:
                    continue
                if left_odd + right_odd != odd_count - 1:
                    continue
            else:
                left_odd = (left_size + 1) // 2
                left_even = left_size // 2
                right_even = (right_size + 1) // 2
                right_odd = right_size // 2

                if left_even + right_even != even_count - 1:
                    continue
                if left_odd + right_odd != odd_count:
                    continue

            if root_odd:
                ways = binomial(odd_count - 1, left_odd) * binomial(even_count, left_even) % MOD
            else:
                ways = binomial(odd_count, left_odd) * binomial(even_count - 1, left_even) % MOD

            left_ways = count_striped(left_size)
            right_ways = count_striped(right_size)

            result = (result + ways * left_ways % MOD * right_ways % MOD) % MOD

        return result

    return count_striped(n)

n = int(input())
print(solve(n))
