import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    return (a * b) // gcd(a, b)

def find_min_max_pair(X):
    if X == 1:
        return 1, 1

    best_a, best_b = 1, X
    limit = int(math.sqrt(X)) + 1

    for a in range(1, min(limit, X + 1)):
        if X % a == 0:
            b = X // a
            if gcd(a, b) == 1:
                if max(a, b) < max(best_a, best_b):
                    best_a, best_b = a, b

    return best_a, best_b

