    for h in range(2, max_height + 1, 2):
        twos.append(h)

    for h in range(3, max_height + 1, 3):
        threes.append(h)

    used = set()

    # Assign heights to students with 3-block pieces
    three_count = 0
    for h in threes:
        if h not in used and three_count < m:
            used.add(h)
            three_count += 1

    if three_count < m:
        return False

    # Assign heights to students with 2-block pieces
    two_count = 0
    for h in twos:
        if h not in used and two_count < n:
            used.add(h)
            two_count += 1

    if two_count < n:
        return False

    return True

left, right = 1, 3 * (n + m)
result = right

while left <= right:
    mid = (left + right) // 2
    if can_build(mid, n, m):
        result = mid
        right = mid - 1
    else:
        left = mid + 1

print(result)
